# 판매 채널 셋에서 들어온 예약을 객실 타입·날짜별로 모아 남은 방과 대조 (가상 값)
inventory = {"DLX": 5, "STE": 1}
bookings = [("OTA-A", "STE", "11-30"), ("OTA-B", "STE", "11-30"), ("WEB", "DLX", "11-30")]
sold = {}
for ch, rt, d in bookings:
    sold[(rt, d)] = sold.get((rt, d), 0) + 1
for (rt, d), n in sold.items():
    left = inventory[rt] - n
    print(rt, d, "판매", n, "남음", left, "<- 초과 판매" if left < 0 else "")
# 출력
# STE 11-30 판매 2 남음 -1 <- 초과 판매
# DLX 11-30 판매 1 남음 4
